import{_ as a,c as t,o as r,a3 as i}from"./chunks/framework.BurWKwwG.js";const m=JSON.parse('{"title":"Data Access","description":"","frontmatter":{},"headers":[],"relativePath":"2.3_access.md","filePath":"2.3_access.md"}'),l={name:"2.3_access.md"};function s(n,e,o,c,d,h){return r(),t("div",null,e[0]||(e[0]=[i('<h1 id="data-access" tabindex="-1">Data Access <a class="header-anchor" href="#data-access" aria-label="Permalink to “Data Access”">​</a></h1><p>CBD3 provides multiple ways to access and explore our comprehensive colorectal cancer biomarker data.</p><h2 id="web-interface" tabindex="-1">Web Interface <a class="header-anchor" href="#web-interface" aria-label="Permalink to “Web Interface”">​</a></h2><h3 id="biomarker-browsing" tabindex="-1">Biomarker Browsing <a class="header-anchor" href="#biomarker-browsing" aria-label="Permalink to “Biomarker Browsing”">​</a></h3><p>The <a href="/docs/biomarker.html">Biomarker</a> page provides structured access to curated biomarker records with pagination and search.</p><h3 id="explore" tabindex="-1">Explore <a class="header-anchor" href="#explore" aria-label="Permalink to “Explore”">​</a></h3><ul><li><strong>Gene Expression Atlas</strong> (<code>/explore</code>): Interactive UMAP visualization of single-cell gene expression. Select a dataset, cell type, and gene to overlay expression levels on the UMAP plot.</li><li><strong>Protein Interaction</strong> (<code>/explore/network</code>): Browse and explore PPI networks with interactive Cytoscape.js graphs.</li></ul><h3 id="single-cell-analyses" tabindex="-1">Single-Cell Analyses <a class="header-anchor" href="#single-cell-analyses" aria-label="Permalink to “Single-Cell Analyses”">​</a></h3><p>The <a href="/docs/analysis.html">Analysis</a> page provides seven analysis modules:</p><table tabindex="0"><thead><tr><th>Module</th><th>Description</th></tr></thead><tbody><tr><td>DEGs</td><td>Differential expressed gene analysis (Original, By Celltype, Tumor vs Normal)</td></tr><tr><td>KEGG Pathway</td><td>KEGG pathway enrichment bubble charts</td></tr><tr><td>Ridge Ranking</td><td>Ridge ranking visualizations</td></tr><tr><td>Trajectory</td><td>Cell trajectory plots and interactive pseudotime analysis</td></tr><tr><td>CellChat</td><td>Cell communication networks (all interactions and biomarker-specific)</td></tr><tr><td>Network Sensitivity</td><td>PRS network sensitivity analysis</td></tr><tr><td>Predictive Ability</td><td>ROC predictive analysis (Tumor vs Normal and By Celltype)</td></tr></tbody></table><h3 id="clinical" tabindex="-1">Clinical <a class="header-anchor" href="#clinical" aria-label="Permalink to “Clinical”">​</a></h3><ul><li><strong>Survival</strong> (<code>/clinical/survival</code>): Kaplan-Meier survival curves with gene and clinical parameter filtering</li><li><strong>Immune</strong> (<code>/clinical/immune</code>): Immune infiltration heatmap (full-data, 800px height)</li></ul><h3 id="other-pages" tabindex="-1">Other Pages <a class="header-anchor" href="#other-pages" aria-label="Permalink to “Other Pages”">​</a></h3><ul><li><strong>Download</strong> (<code>/download</code>): Download data files</li><li><strong>Submit</strong> (<code>/submit</code>): Submit new biomarker data</li></ul><h2 id="api-access" tabindex="-1">API Access <a class="header-anchor" href="#api-access" aria-label="Permalink to “API Access”">​</a></h2><ul><li><strong>RESTful API</strong>: Programmatic access to all CBD3 data</li><li>API documentation is under construction</li></ul><h2 id="access-levels" tabindex="-1">Access Levels <a class="header-anchor" href="#access-levels" aria-label="Permalink to “Access Levels”">​</a></h2><ul><li><strong>No Registration Required</strong>: Full browsing, searching, and downloading</li></ul><h2 id="data-citation" tabindex="-1">Data Citation <a class="header-anchor" href="#data-citation" aria-label="Permalink to “Data Citation”">​</a></h2><p>When using CBD3 data, please cite the database and the original data sources where applicable.</p>',20)]))}const g=a(l,[["render",s]]);export{m as __pageData,g as default};
